UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 33, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 34, 7, NULL::text),(3, 162, 51, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 217, 1210, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='4f948c8a-0d3d-596c-a628-f9bfc5fdaea1' AND md5(a.contenido)='861e25d4eeb8a65b32539ecba55367d4' RETURNING a.id,md5(a.contenido) hash;